    center = `<text x="14" y="${String(label).length >= 2 ? 16.6 : 17}" font-family="system-ui, sans-serif" font-size="${fs}" font-weight="800" fill="${txt}" text-anchor="middle" letter-spacing="-0.5">${label}</text>`;
