    const txt = hollow ? color : readableTextColor(color);
    center = `<text x="14" y="16.8" font-family="system-ui, sans-serif" font-size="10" font-weight="800" fill="${txt}" text-anchor="middle" letter-spacing="-0.5">${tag}</text>`;
